<script setup>
import { reactive } from 'vue';import { router } from '@inertiajs/vue3';import AppShell from '@/Components/AppShell.vue';import SortButton from '@/Components/SortButton.vue';import DataTableFooter from '@/Components/DataTableFooter.vue';
const p=defineProps({reports:Object,filters:Object});const f=reactive({search:'',sort:'arrived_at',direction:'desc',per_page:10,...p.filters});const load=()=>router.get('/vendor/monitoring-sarana',f,{preserveState:true,preserveScroll:true,replace:true});const sort=c=>{f.direction=f.sort===c&&f.direction==='asc'?'desc':'asc';f.sort=c;load()};const size=v=>{f.per_page=v;load()};const date=v=>new Date(v).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'});
</script>
<template><AppShell title="Monitoring Sarana" subtitle="Pantau kedatangan sarana yang terkait dengan akun vendor Anda." eyebrow="Akun Vendor"><form class="panel mb-5 flex flex-col gap-3 sm:flex-row" @submit.prevent="load"><input v-model="f.search" class="control flex-1" placeholder="Cari nomor laporan, driver, nopol, tujuan..."/><button class="btn">Cari Data</button></form><section class="panel overflow-hidden p-0"><div class="border-b px-5 py-4"><h2 class="panel-title">Kedatangan Sarana Saya</h2><p class="panel-copy">DataTable server-side · hanya data vendor yang terhubung dengan akun ini</p></div><div class="overflow-x-auto"><table class="data-table min-w-[1000px]"><thead><tr><th>No</th><th><SortButton label="Waktu" column="arrived_at" :sort="f.sort" :direction="f.direction" @sort="sort"/></th><th><SortButton label="Ekspedisi" column="expedition_company" :sort="f.sort" :direction="f.direction" @sort="sort"/></th><th><SortButton label="Driver" column="driver_name" :sort="f.sort" :direction="f.direction" @sort="sort"/></th><th><SortButton label="Nopol" column="vehicle_plate" :sort="f.sort" :direction="f.direction" @sort="sort"/></th><th>Kendaraan</th><th>Vendor</th><th>Tujuan</th></tr></thead><tbody><tr v-for="(x,i) in reports.data" :key="x.id"><td>{{reports.from+i}}</td><td>{{date(x.arrived_at)}}</td><td>{{x.expedition_company}}</td><td>{{x.driver_name}}</td><td><b>{{x.vehicle_plate}}</b></td><td>{{x.vehicle_type}}</td><td>{{x.sender_vendor}}</td><td>{{x.destination}}</td></tr></tbody></table><div v-if="!reports.data.length" class="p-14 text-center text-sm text-slate-500">Belum ada kedatangan sarana yang terkait dengan akun ini.</div></div><DataTableFooter :paginator="reports" :per-page="f.per_page" @update:per-page="size"/></section></AppShell></template>
